// Validate & Clean (ARCHITECTURE.md 2.3)
// Confirms required fields, normalizes types, dedupes by full-row match
// (every attribute identical, not just Email), tags each row with
// _validation_status instead of dropping silently.

const REQUIRED_FIELDS = ['Name', 'Email'];
const EMAIL_RE = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;

function parseDate(value) {
  if (!value) return null;
  const str = String(value).trim();
  const formats = [
    { re: /^(\d{4})-(\d{2})-(\d{2})$/, order: ['y','m','d'] },
    { re: /^(\d{2})\/(\d{2})\/(\d{4})$/, order: ['m','d','y'] },
    { re: /^(\d{2})-(\d{2})-(\d{4})$/, order: ['m','d','y'] },
    { re: /^(\d{4})\/(\d{2})\/(\d{2})$/, order: ['y','m','d'] },
  ];
  for (const fmt of formats) {
    const m = str.match(fmt.re);
    if (m) {
      const parts = {};
      fmt.order.forEach((key, i) => { parts[key] = parseInt(m[i + 1], 10); });
      const d = new Date(Date.UTC(parts.y, parts.m - 1, parts.d));
      if (!isNaN(d.getTime())) return d;
    }
  }
  return null;
}

function parseAmount(value) {
  if (value === null || value === undefined || value === '') return null;
  const cleaned = String(value).replace('$', '').replace(/,/g, '').trim();
  const num = parseFloat(cleaned);
  return isNaN(num) ? null : num;
}

// Builds a canonical signature from every attribute on the row so two rows
// only count as duplicates when ALL fields match exactly — not just Email.
// Uses normalized Email/amount/date (so formatting differences like
// "$50" vs "50.00" or "1/2/2025" vs "2025-01-02" don't hide a true dup),
// and trims/stringifies every other field for a stable comparison.
function buildRowSignature(row, normalizedEmail, normalizedAmount, normalizedDate) {
  const comparable = { ...row };
  comparable.Email = normalizedEmail;
  comparable['Donation amount'] = normalizedAmount;
  comparable['Donation date'] = normalizedDate;

  return Object.keys(comparable)
    .sort()
    .map((key) => `${key}=${String(comparable[key] ?? '').trim().toLowerCase()}`)
    .join('|');
}

const seenRowSignatures = new Set();
const output = [];

for (const item of $input.all()) {
  const row = { ...item.json };
  const reasons = [];

  for (const field of REQUIRED_FIELDS) {
    if (!row[field]) reasons.push(`missing_${field.toLowerCase()}`);
  }

  const emailRaw = String(row.Email || '').trim().toLowerCase();
  if (emailRaw && !EMAIL_RE.test(emailRaw)) reasons.push('malformed_email');

  const amount = parseAmount(row['Donation amount'] ?? row['DonationAmount']);
  const date = parseDate(row['Donation date'] ?? row['DonationDate']);
  if (amount === null) reasons.push('missing_or_invalid_donation_amount');
  if (date === null) reasons.push('missing_or_invalid_donation_date');

  const signature = buildRowSignature(row, emailRaw, amount, date ? date.toISOString() : null);
  if (seenRowSignatures.has(signature)) {
    reasons.push('duplicate_row');
  } else {
    seenRowSignatures.add(signature);
  }

  row.Email = emailRaw;
  row._donation_amount = amount;
  row._donation_date = date ? date.toISOString() : null;
  row._validation_status = reasons.length ? 'invalid' : 'valid';
  row._validation_reason = reasons.join(',');

  output.push({ json: row });
}

return output;

// Behavioral Segmentation (ARCHITECTURE.md 2.6)
// Independent secondary signal, cross-tabbed with RFM rather than
// folded into one score. Degrades gracefully if engagement fields are missing.

const output = [];
for (const item of $input.all()) {
  const row = { ...item.json };

  const events = row['Events attended'] || row['EventsAttended'] || '';
  const comms = row['Communications leading up to the donation'] || row['Communications'] || '';

  const eventsCount = events ? String(events).split(';').filter(e => e.trim()).length : 0;
  const commsCount = comms ? String(comms).split(';').filter(c => c.trim()).length : 0;

  let tag;
  if (eventsCount === 0 && commsCount === 0) tag = 'insufficient_data';
  else if (eventsCount > 0 && commsCount === 0) tag = 'event_driven';
  else if (eventsCount === 0 && commsCount > 0) tag = 'email_only';
  else tag = 'mixed_channel';

  const frequency = row.rfm_frequency_score || 1;
  const responsiveness = tag === 'insufficient_data'
    ? 'unknown'
    : (commsCount >= frequency ? 'campaign_responsive' : 'steady_giver');

  row.behavioral_tag = tag;
  row.responsiveness = responsiveness;
  output.push({ json: row });
}

return output;

